	`status` text DEFAULT 'draft' NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`review_id`) REFERENCES `reviews`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "ck_extraction_forms_version" CHECK("version" >= 1),
	CONSTRAINT "ck_extraction_forms_status" CHECK("status" in ('draft', 'active', 'locked')),
	CONSTRAINT "ck_extraction_forms_template" CHECK("template" is null or "template" in ('rct', 'observational', 'diagnostic', 'qualitative', 'custom')),
	CONSTRAINT "ck_extraction_forms_schema_json" CHECK(json_valid("schema_json")),
	CONSTRAINT "ck_extraction_forms_groups_json" CHECK(json_valid("repeatable_groups"))
);
